protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex throws in EF Core 9 Cosmos — manage indexing via Azure portal/Bicep.
    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 changed the default discriminator property from "Discriminator" to "$type".
    // Preserve "Discriminator" so existing 500K documents remain queryable,
    // and so direct SQL queries referencing c.Discriminator keep working.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 changed id format from "Product|123" to just "123".
    // Preserve the old compound format so existing documents are still found by FindAsync.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

